FormulaFieldDefinitions.FormulaFieldDefinition:
whileprintingrecords;
stringvar group1:= {@fGroup1};
stringvar group2:= {@fGroup2};

stringvar groupsSRT;
if onfirstrecord then groupsSRT:= '||';

groupsSRT:= groupsSRT + group1 + group2 + '|' + totext(pagenumber,0) + '||';

FontColorConditionFormulas.Style:
// This conditional formatting formula must return one of the following Font Style Constants:
// 
// crRegular
// crBold
// crItalic
// crBoldItalic
// 
if ({Command.QryGroup14}) = "Y" THEN
crBoldItalic
else
crRegular;

// This conditional formatting formula must return one of the following Font Style Constants:
